28	/*
29	    Parallel reduction kernels
30	*/
31	
32	#ifndef _REDUCE_KERNEL_H_
33	#define _REDUCE_KERNEL_H_
34	
35	#include <cooperative_groups.h>
36	#include <stdio.h>
37	
38	namespace cg = cooperative_groups;
