40	// Utility class used to avoid linker errors with extern
41	// unsized shared memory arrays with templated type
42	template <class T>
43	struct SharedMemory {
44	  __device__ inline operator T *() {
45	    extern __shared__ int __smem[];
46	    return (T *)__smem;
47	  }
48	
49	  __device__ inline operator const T *() const {
50	    extern __shared__ int __smem[];
51	    return (T *)__smem;
52	  }
53	};
54	
55	// specialize for double to avoid unaligned memory
56	// access compile errors
57	template <>
58	struct SharedMemory<double> {
59	  __device__ inline operator double *() {
60	    extern __shared__ double __smem_d[];
61	    return (double *)__smem_d;
62	  }
63	
64	  __device__ inline operator const double *() const {
65	    extern __shared__ double __smem_d[];
66	    return (double *)__smem_d;
67	  }
68	};
