171	template <class T>
172	__inline__ __device__ T warpReduceSum(T val) {
173	  for (int offset = warpSize/2; offset > 0; offset /= 2) 
174	    val += __shfl_down_sync((unsigned int)-1, val, offset);
175	  return val;
176	}
177	
178	/*
179	    This version uses n/2 threads --
180	    it performs the first level of reduction when reading from global memory.
181	*/
182	template <class T>
183	__global__ void reduce3(T *g_idata, T *g_odata, unsigned int n) {
184	  // Handle to thread block group
185	  cg::thread_block cta = cg::this_thread_block();
186	  T *sdata = SharedMemory<T>();
187	
188	  // perform first level of reduction,
189	  // reading from global memory, writing to shared memory
190	  unsigned int tid = threadIdx.x;
191	  unsigned int i = blockIdx.x * (blockDim.x * 2) + threadIdx.x;
192	
193	  T mySum = (i < n) ? g_idata[i] : 0;
194	
195	  if (i + blockDim.x < n) mySum += g_idata[i + blockDim.x];
196	
197	  // do reduction using shuffle instruction
198	  mySum = warpReduceSum<T>(mySum);
199	  int lane = threadIdx.x % warpSize;
200	  int wid = threadIdx.x / warpSize;
201	  if (lane == 0) sdata[wid] = mySum;
202	  cg::sync(cta);
203	  mySum = (threadIdx.x < blockDim.x / warpSize) ? sdata[lane] : 0;
204	  if (wid == 0) mySum = warpReduceSum<T>(mySum);
205	
206	  // write result for this block to global mem
207	  if (tid == 0) g_odata[blockIdx.x] = mySum;
208	}
