210	/*
211	    This version uses the warp shuffle operation if available to reduce
212	    warp synchronization. When shuffle is not available the final warp's
213	    worth of work is unrolled to reduce looping overhead.
214	
215	    See
216	   http://devblogs.nvidia.com/parallelforall/faster-parallel-reductions-kepler/
217	    for additional information about using shuffle to perform a reduction
218	    within a warp.
219	
220	    Note, this kernel needs a minimum of 64*sizeof(T) bytes of shared memory.
221	    In other words if blockSize <= 32, allocate 64*sizeof(T) bytes.
222	    If blockSize > 32, allocate blockSize*sizeof(T) bytes.
223	*/
224	template <class T, unsigned int blockSize>
225	__global__ void reduce4(T *g_idata, T *g_odata, unsigned int n) {
226	  // Handle to thread block group
227	  cg::thread_block cta = cg::this_thread_block();
228	  T *sdata = SharedMemory<T>();
229	
230	  // perform first level of reduction,
231	  // reading from global memory, writing to shared memory
232	  unsigned int tid = threadIdx.x;
233	  unsigned int i = blockIdx.x * (blockDim.x * 2) + threadIdx.x;
234	
235	  T mySum = (i < n) ? g_idata[i] : 0;
236	
237	  if (i + blockSize < n) mySum += g_idata[i + blockSize];
238	
239	  sdata[tid] = mySum;
240	  cg::sync(cta);
241	
242	  // do reduction in shared mem
243	  for (unsigned int s = blockDim.x / 2; s > 32; s >>= 1) {
244	    if (tid < s) {
245	      sdata[tid] = mySum = mySum + sdata[tid + s];
246	    }
247	
248	    cg::sync(cta);
249	  }
250	
251	  cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
252	
253	  if (cta.thread_rank() < 32) {
254	    // Fetch final intermediate sum from 2nd warp
255	    if (blockSize >= 64) mySum += sdata[tid + 32];
256	    // Reduce final warp using shuffle
257	    for (int offset = tile32.size() / 2; offset > 0; offset /= 2) {
258	      mySum += tile32.shfl_down(mySum, offset);
259	    }
260	  }
261	
262	  // write result for this block to global mem
263	  if (cta.thread_rank() == 0) g_odata[blockIdx.x] = mySum;
264	}
