266	/*
267	    This version is completely unrolled, unless warp shuffle is available, then
268	    shuffle is used within a loop.  It uses a template parameter to achieve
269	    optimal code for any (power of 2) number of threads.  This requires a switch
270	    statement in the host code to handle all the different thread block sizes at
271	    compile time. When shuffle is available, it is used to reduce warp
272	   synchronization.
273	
274	    Note, this kernel needs a minimum of 64*sizeof(T) bytes of shared memory.
275	    In other words if blockSize <= 32, allocate 64*sizeof(T) bytes.
276	    If blockSize > 32, allocate blockSize*sizeof(T) bytes.
277	*/
278	template <class T, unsigned int blockSize>
279	__global__ void reduce5(T *g_idata, T *g_odata, unsigned int n) {
280	  // Handle to thread block group
281	  cg::thread_block cta = cg::this_thread_block();
282	  T *sdata = SharedMemory<T>();
283	
284	  // perform first level of reduction,
285	  // reading from global memory, writing to shared memory
286	  unsigned int tid = threadIdx.x;
287	  unsigned int i = blockIdx.x * (blockSize * 2) + threadIdx.x;
288	
289	  T mySum = (i < n) ? g_idata[i] : 0;
290	
291	  if (i + blockSize < n) mySum += g_idata[i + blockSize];
292	
293	  sdata[tid] = mySum;
294	  cg::sync(cta);
295	
296	  // do reduction in shared mem
297	  if ((blockSize >= 512) && (tid < 256)) {
298	    sdata[tid] = mySum = mySum + sdata[tid + 256];
299	  }
300	
301	  cg::sync(cta);
302	
303	  if ((blockSize >= 256) && (tid < 128)) {
304	    sdata[tid] = mySum = mySum + sdata[tid + 128];
305	  }
306	
307	  cg::sync(cta);
308	
309	  if ((blockSize >= 128) && (tid < 64)) {
310	    sdata[tid] = mySum = mySum + sdata[tid + 64];
311	  }
312	
313	  cg::sync(cta);
314	
315	  cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
316	
317	  if (cta.thread_rank() < 32) {
318	    // Fetch final intermediate sum from 2nd warp
319	    if (blockSize >= 64) mySum += sdata[tid + 32];
320	    // Reduce final warp using shuffle
321	    for (int offset = tile32.size() / 2; offset > 0; offset /= 2) {
322	      mySum += tile32.shfl_down(mySum, offset);
323	    }
324	  }
325	
326	  // write result for this block to global mem
327	  if (cta.thread_rank() == 0) g_odata[blockIdx.x] = mySum;
328	}
329	
330	/*
331	    This version adds multiple elements per thread sequentially.  This reduces
332	   the overall cost of the algorithm while keeping the work complexity O(n) and
333	   the step complexity O(log n). (Brent's Theorem optimization)
334	
335	    Note, this kernel needs a minimum of 64*sizeof(T) bytes of shared memory.
336	    In other words if blockSize <= 32, allocate 64*sizeof(T) bytes.
337	    If blockSize > 32, allocate blockSize*sizeof(T) bytes.
338	*/
339	template <class T, unsigned int blockSize, bool nIsPow2>
340	__global__ void reduce6(T *g_idata, T *g_odata, unsigned int n) {
341	  // Handle to thread block group
342	  cg::thread_block cta = cg::this_thread_block();
343	  T *sdata = SharedMemory<T>();
344	
345	  // perform first level of reduction,
346	  // reading from global memory, writing to shared memory
347	  unsigned int tid = threadIdx.x;
348	  unsigned int i = blockIdx.x * blockSize * 2 + threadIdx.x;
349	  unsigned int gridSize = blockSize * 2 * gridDim.x;
350	
351	  T mySum = 0;
352	
353	  // we reduce multiple elements per thread.  The number is determined by the
354	  // number of active thread blocks (via gridDim).  More blocks will result
355	  // in a larger gridSize and therefore fewer elements per thread
356	  while (i < n) {
357	    mySum += g_idata[i];
358	
359	    // ensure we don't read out of bounds -- this is optimized away for powerOf2
360	    // sized arrays
361	    if (nIsPow2 || i + blockSize < n) mySum += g_idata[i + blockSize];
362	
363	    i += gridSize;
364	  }
365	
366	  // each thread puts its local sum into shared memory
367	  sdata[tid] = mySum;
368	  cg::sync(cta);
369	
370	  // do reduction in shared mem
371	  if ((blockSize >= 512) && (tid < 256)) {
372	    sdata[tid] = mySum = mySum + sdata[tid + 256];
373	  }
374	
375	  cg::sync(cta);
376	
377	  if ((blockSize >= 256) && (tid < 128)) {
378	    sdata[tid] = mySum = mySum + sdata[tid + 128];
379	  }
380	
381	  cg::sync(cta);
382	
383	  if ((blockSize >= 128) && (tid < 64)) {
384	    sdata[tid] = mySum = mySum + sdata[tid + 64];
385	  }
386	
387	  cg::sync(cta);
388	
389	  cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
390	
391	  if (cta.thread_rank() < 32) {
392	    // Fetch final intermediate sum from 2nd warp
393	    if (blockSize >= 64) mySum += sdata[tid + 32];
394	    // Reduce final warp using shuffle
395	    for (int offset = tile32.size() / 2; offset > 0; offset /= 2) {
396	      mySum += tile32.shfl_down(mySum, offset);
397	    }
398	  }
399	
400	  // write result for this block to global mem
401	  if (cta.thread_rank() == 0) g_odata[blockIdx.x] = mySum;
402	}
