462	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
463	          break;
464	
465	        case 16:
466	          reduce4<T, 16>
467	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
468	          break;
469	
470	        case 8:
471	          reduce4<T, 8>
472	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
473	          break;
474	
475	        case 4:
476	          reduce4<T, 4>
477	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
478	          break;
479	
480	        case 2:
481	          reduce4<T, 2>
482	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
483	          break;
484	
485	        case 1:
486	          reduce4<T, 1>
487	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
488	          break;
489	      }
490	
491	      break;
492	
493	    case 5:
494	      switch (threads) {
495	        case 512:
496	          reduce5<T, 512>
497	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
498	          break;
499	
500	        case 256:
501	          reduce5<T, 256>
502	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
503	          break;
504	
505	        case 128:
506	          reduce5<T, 128>
507	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
508	          break;
509	
510	        case 64:
511	          reduce5<T, 64>
512	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
513	          break;
514	
515	        case 32:
516	          reduce5<T, 32>
517	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
518	          break;
519	
520	        case 16:
521	          reduce5<T, 16>
522	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
523	          break;
524	
525	        case 8:
526	          reduce5<T, 8>
527	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
528	          break;
529	
530	        case 4:
531	          reduce5<T, 4>
532	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
533	          break;
534	
535	        case 2:
536	          reduce5<T, 2>
537	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
538	          break;
539	
540	        case 1:
541	          reduce5<T, 1>
542	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
