579	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
580	            break;
581	
582	          case 8:
583	            reduce6<T, 8, true>
584	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
585	            break;
586	
587	          case 4:
588	            reduce6<T, 4, true>
589	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
590	            break;
591	
592	          case 2:
593	            reduce6<T, 2, true>
594	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
595	            break;
596	
597	          case 1:
598	            reduce6<T, 1, true>
599	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
600	            break;
601	        }
602	      } else {
603	        switch (threads) {
604	          case 512:
605	            reduce6<T, 512, false>
606	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
607	            break;
608	
609	          case 256:
610	            reduce6<T, 256, false>
611	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
612	            break;
