614	          case 128:
615	            reduce6<T, 128, false>
616	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
617	            break;
618	
619	          case 64:
620	            reduce6<T, 64, false>
621	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
622	            break;
623	
624	          case 32:
625	            reduce6<T, 32, false>
626	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
627	            break;
628	
629	          case 16:
630	            reduce6<T, 16, false>
631	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
632	            break;
633	
634	          case 8:
635	            reduce6<T, 8, false>
636	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
637	            break;
638	
639	          case 4:
640	            reduce6<T, 4, false>
641	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
642	            break;
643	
644	          case 2:
645	            reduce6<T, 2, false>
646	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
647	            break;
648	
649	          case 1:
650	            reduce6<T, 1, false>
651	                <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
652	            break;
653	        }
654	      }
655	
656	      break;
657	  }
658	}
