59	  __device__ inline operator double *() {
60	    extern __shared__ double __smem_d[];
61	    return (double *)__smem_d;
62	  }
63	
64	  __device__ inline operator const double *() const {
65	    extern __shared__ double __smem_d[];
66	    return (double *)__smem_d;
67	  }
68	};
69	
70	/*
71	    Parallel sum reduction using shared memory
72	    - takes log(n) steps for n input elements
73	    - uses n threads
74	    - only works for power-of-2 arrays
75	*/
76	
77	/* This reduction interleaves which threads are active by using the modulo
78	   operator.  This operator is very expensive on GPUs, and the interleaved
79	   inactivity means that no whole warps are active, which is also very
80	   inefficient */
81	template <class T>
82	__global__ void reduce0(T *g_idata, T *g_odata, unsigned int n) {
83	  // Handle to thread block group
84	  cg::thread_block cta = cg::this_thread_block();
85	  T *sdata = SharedMemory<T>();
86	
87	  // load shared mem
88	  unsigned int tid = threadIdx.x;
89	  unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
90	
91	  sdata[tid] = (i < n) ? g_idata[i] : 0;
92	
93	  cg::sync(cta);
94	
95	  // do reduction in shared mem
96	  for (unsigned int s = 1; s < blockDim.x; s *= 2) {
97	    // modulo arithmetic is slow!
98	    if ((tid % (2 * s)) == 0) {
99	      sdata[tid] += sdata[tid + s];
100	    }
101	
102	    cg::sync(cta);
103	  }
104	
105	  // write result for this block to global mem
106	  if (tid == 0) g_odata[blockIdx.x] = sdata[0];
107	}
108	
109	/* This version uses contiguous threads, but its interleaved
110	   addressing results in many shared memory bank conflicts.
111	*/
112	template <class T>
113	__global__ void reduce1(T *g_idata, T *g_odata, unsigned int n) {
114	  // Handle to thread block group
115	  cg::thread_block cta = cg::this_thread_block();
116	  T *sdata = SharedMemory<T>();
117	
118	  // load shared mem
119	  unsigned int tid = threadIdx.x;
120	  unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
121	
122	  sdata[tid] = (i < n) ? g_idata[i] : 0;
123	
124	  cg::sync(cta);
125	
126	  // do reduction in shared mem
127	  for (unsigned int s = 1; s < blockDim.x; s *= 2) {
128	    int index = 2 * s * tid;
129	
130	    if (index < blockDim.x) {
131	      sdata[index] += sdata[index + s];
132	    }
133	
134	    cg::sync(cta);
135	  }
136	
137	  // write result for this block to global mem
138	  if (tid == 0) g_odata[blockIdx.x] = sdata[0];
139	}
140	
141	/*
142	    This version uses sequential addressing -- no divergence or bank conflicts.
143	*/
144	template <class T>
145	__global__ void reduce2(T *g_idata, T *g_odata, unsigned int n) {
146	  // Handle to thread block group
147	  cg::thread_block cta = cg::this_thread_block();
148	  T *sdata = SharedMemory<T>();
149	
150	  // load shared mem
151	  unsigned int tid = threadIdx.x;
152	  unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
153	
154	  sdata[tid] = (i < n) ? g_idata[i] : 0;
155	
156	  cg::sync(cta);
157	
158	  // do reduction in shared mem
159	  for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
160	    if (tid < s) {
161	      sdata[tid] += sdata[tid + s];
162	    }
163	
164	    cg::sync(cta);
165	  }
166	
167	  // write result for this block to global mem
168	  if (tid == 0) g_odata[blockIdx.x] = sdata[0];
169	}
170	
171	/*
172	    This version uses n/2 threads --
173	    it performs the first level of reduction when reading from global memory.
174	*/
175	template <class T>
176	__global__ void reduce3(T *g_idata, T *g_odata, unsigned int n) {
177	  // Handle to thread block group
178	  cg::thread_block cta = cg::this_thread_block();
179	
180	  // perform first level of reduction,
181	  // reading from global memory, writing to shared memory
182	  unsigned int tid = threadIdx.x;
183	  unsigned int i = blockIdx.x * (blockDim.x * 2) + threadIdx.x;
184	
185	  T mySum = (i < n) ? g_idata[i] : 0;
186	
187	  if (i + blockDim.x < n) mySum += g_idata[i + blockDim.x];
188	
189	  g_odata[i] = mySum;
190	  cg::sync(cta);
191	
192	  // do reduction in global mem
193	  for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
194	    if (tid < s) {
195	      g_odata[i] = mySum = mySum + g_odata[i + s];
196	    }
197	    cg::sync(cta);
198	  }
199	
200	  // write result for this block to global mem
201	  if (tid == 0) g_odata[blockIdx.x] = mySum;
202	}
203	
204	/*
205	    This version uses the warp shuffle operation if available to reduce
206	    warp synchronization. When shuffle is not available the final warp's
207	    worth of work is unrolled to reduce looping overhead.
208	
209	    See
210	   http://devblogs.nvidia.com/parallelforall/faster-parallel-reductions-kepler/
211	    for additional information about using shuffle to perform a reduction
212	    within a warp.
213	
214	    Note, this kernel needs a minimum of 64*sizeof(T) bytes of shared memory.
215	    In other words if blockSize <= 32, allocate 64*sizeof(T) bytes.
216	    If blockSize > 32, allocate blockSize*sizeof(T) bytes.
217	*/
218	template <class T, unsigned int blockSize>
219	__global__ void reduce4(T *g_idata, T *g_odata, unsigned int n) {
220	  // Handle to thread block group
221	  cg::thread_block cta = cg::this_thread_block();
222	  T *sdata = SharedMemory<T>();
223	
224	  // perform first level of reduction,
225	  // reading from global memory, writing to shared memory
226	  unsigned int tid = threadIdx.x;
227	  unsigned int i = blockIdx.x * (blockDim.x * 2) + threadIdx.x;
228	
229	  T mySum = (i < n) ? g_idata[i] : 0;
230	
231	  if (i + blockSize < n) mySum += g_idata[i + blockSize];
232	
233	  sdata[tid] = mySum;
234	  cg::sync(cta);
235	
236	  // do reduction in shared mem
237	  for (unsigned int s = blockDim.x / 2; s > 32; s >>= 1) {
238	    if (tid < s) {
239	      sdata[tid] = mySum = mySum + sdata[tid + s];
240	    }
241	
242	    cg::sync(cta);
243	  }
244	
245	  cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
246	
247	  if (cta.thread_rank() < 32) {
248	    // Fetch final intermediate sum from 2nd warp
249	    if (blockSize >= 64) mySum += sdata[tid + 32];
250	    // Reduce final warp using shuffle
251	    for (int offset = tile32.size() / 2; offset > 0; offset /= 2) {
252	      mySum += tile32.shfl_down(mySum, offset);
253	    }
254	  }
255	
256	  // write result for this block to global mem
257	  if (cta.thread_rank() == 0) g_odata[blockIdx.x] = mySum;
258	}
259	
260	/*
261	    This version is completely unrolled, unless warp shuffle is available, then
262	    shuffle is used within a loop.  It uses a template parameter to achieve
263	    optimal code for any (power of 2) number of threads.  This requires a switch
264	    statement in the host code to handle all the different thread block sizes at
265	    compile time. When shuffle is available, it is used to reduce warp
266	   synchronization.
267	
268	    Note, this kernel needs a minimum of 64*sizeof(T) bytes of shared memory.
269	    In other words if blockSize <= 32, allocate 64*sizeof(T) bytes.
270	    If blockSize > 32, allocate blockSize*sizeof(T) bytes.
271	*/
272	template <class T, unsigned int blockSize>
273	__global__ void reduce5(T *g_idata, T *g_odata, unsigned int n) {
274	  // Handle to thread block group
275	  cg::thread_block cta = cg::this_thread_block();
276	  T *sdata = SharedMemory<T>();
277	
278	  // perform first level of reduction,
279	  // reading from global memory, writing to shared memory
280	  unsigned int tid = threadIdx.x;
281	  unsigned int i = blockIdx.x * (blockSize * 2) + threadIdx.x;
282	
283	  T mySum = (i < n) ? g_idata[i] : 0;
284	
285	  if (i + blockSize < n) mySum += g_idata[i + blockSize];
286	
287	  sdata[tid] = mySum;
288	  cg::sync(cta);
289	
290	  // do reduction in shared mem
291	  if ((blockSize >= 512) && (tid < 256)) {
292	    sdata[tid] = mySum = mySum + sdata[tid + 256];
293	  }
294	
295	  cg::sync(cta);
296	
297	  if ((blockSize >= 256) && (tid < 128)) {
298	    sdata[tid] = mySum = mySum + sdata[tid + 128];
299	  }
300	
301	  cg::sync(cta);
302	
303	  if ((blockSize >= 128) && (tid < 64)) {
304	    sdata[tid] = mySum = mySum + sdata[tid + 64];
305	  }
306	
307	  cg::sync(cta);
308	
309	  cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
310	
311	  if (cta.thread_rank() < 32) {
312	    // Fetch final intermediate sum from 2nd warp
313	    if (blockSize >= 64) mySum += sdata[tid + 32];
314	    // Reduce final warp using shuffle
315	    for (int offset = tile32.size() / 2; offset > 0; offset /= 2) {
316	      mySum += tile32.shfl_down(mySum, offset);
317	    }
318	  }
319	
320	  // write result for this block to global mem
321	  if (cta.thread_rank() == 0) g_odata[blockIdx.x] = mySum;
322	}
323	
324	/*
325	    This version adds multiple elements per thread sequentially.  This reduces
326	   the overall cost of the algorithm while keeping the work complexity O(n) and
327	   the step complexity O(log n). (Brent's Theorem optimization)
328	
329	    Note, this kernel needs a minimum of 64*sizeof(T) bytes of shared memory.
330	    In other words if blockSize <= 32, allocate 64*sizeof(T) bytes.
331	    If blockSize > 32, allocate blockSize*sizeof(T) bytes.
332	*/
333	template <class T, unsigned int blockSize, bool nIsPow2>
334	__global__ void reduce6(T *g_idata, T *g_odata, unsigned int n) {
335	  // Handle to thread block group
336	  cg::thread_block cta = cg::this_thread_block();
337	  T *sdata = SharedMemory<T>();
338	
339	  // perform first level of reduction,
340	  // reading from global memory, writing to shared memory
341	  unsigned int tid = threadIdx.x;
342	  unsigned int i = blockIdx.x * blockSize * 2 + threadIdx.x;
343	  unsigned int gridSize = blockSize * 2 * gridDim.x;
344	
345	  T mySum = 0;
346	
347	  // we reduce multiple elements per thread.  The number is determined by the
348	  // number of active thread blocks (via gridDim).  More blocks will result
349	  // in a larger gridSize and therefore fewer elements per thread
350	  while (i < n) {
351	    mySum += g_idata[i];
352	
353	    // ensure we don't read out of bounds -- this is optimized away for powerOf2
354	    // sized arrays
355	    if (nIsPow2 || i + blockSize < n) mySum += g_idata[i + blockSize];
356	
357	    i += gridSize;
358	  }
359	
360	  // each thread puts its local sum into shared memory
361	  sdata[tid] = mySum;
362	  cg::sync(cta);
363	
364	  // do reduction in shared mem
365	  if ((blockSize >= 512) && (tid < 256)) {
366	    sdata[tid] = mySum = mySum + sdata[tid + 256];
367	  }
368	
369	  cg::sync(cta);
370	
371	  if ((blockSize >= 256) && (tid < 128)) {
372	    sdata[tid] = mySum = mySum + sdata[tid + 128];
373	  }
374	
375	  cg::sync(cta);
376	
377	  if ((blockSize >= 128) && (tid < 64)) {
378	    sdata[tid] = mySum = mySum + sdata[tid + 64];
379	  }
380	
381	  cg::sync(cta);
382	
383	  cg::thread_block_tile<32> tile32 = cg::tiled_partition<32>(cta);
384	
385	  if (cta.thread_rank() < 32) {
386	    // Fetch final intermediate sum from 2nd warp
387	    if (blockSize >= 64) mySum += sdata[tid + 32];
388	    // Reduce final warp using shuffle
389	    for (int offset = tile32.size() / 2; offset > 0; offset /= 2) {
390	      mySum += tile32.shfl_down(mySum, offset);
391	    }
392	  }
393	
394	  // write result for this block to global mem
395	  if (cta.thread_rank() == 0) g_odata[blockIdx.x] = mySum;
396	}
