400	////////////////////////////////////////////////////////////////////////////////
401	// Wrapper function for kernel launch
402	////////////////////////////////////////////////////////////////////////////////
403	template <class T>
404	void reduce(int size, int threads, int blocks, int whichKernel, T *d_idata,
405	            T *d_odata) {
406	  dim3 dimBlock(threads, 1, 1);
407	  dim3 dimGrid(blocks, 1, 1);
408	
409	  // when there is only one warp per block, we need to allocate two warps
