472	          break;
473	
474	        case 2:
475	          reduce4<T, 2>
476	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
477	          break;
478	
479	        case 1:
480	          reduce4<T, 1>
481	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
482	          break;
483	      }
484	
485	      break;
486	
487	    case 5:
488	      switch (threads) {
489	        case 512:
490	          reduce5<T, 512>
491	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
492	          break;
493	
494	        case 256:
495	          reduce5<T, 256>
496	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
497	          break;
498	
499	        case 128:
500	          reduce5<T, 128>
501	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
502	          break;
503	
504	        case 64:
505	          reduce5<T, 64>
506	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
507	          break;
508	
509	        case 32:
510	          reduce5<T, 32>
511	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
512	          break;
513	
514	        case 16:
515	          reduce5<T, 16>
516	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
517	          break;
518	
519	        case 8:
520	          reduce5<T, 8>
521	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
522	          break;
523	
524	        case 4:
525	          reduce5<T, 4>
526	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
527	          break;
528	
529	        case 2:
530	          reduce5<T, 2>
531	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
532	          break;
533	
534	        case 1:
535	          reduce5<T, 1>
536	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
537	          break;
538	      }
539	
540	      break;
541	
542	    case 6:
543	    default:
